VALUES (NULL, NULL, 10344, 'Galactic Civilizations', 'Galactic Civilizations', 'game', 2003, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4lca.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scsvay.jpg', 'Galactic Civilizations is a space based strategy game in which you are in control of humanity''s destiny. The year is 2178, the Terran Alliance has invented a new technology -- Hyperdrive. But the secret has leaked to the other civilizations starting a race for all the inhabitable worlds in the galaxy! As leader of United Earth, you must research new technologies, build an economy, create a powerful military force, all the while carefully balancing your political, diplomatic and trade skills.', 'https://www.igdb.com/games/galactic-civilizations', '["PC (Microsoft Windows)"]', NULL, 7.5, 0, 8.02, '2026-11-23 15:29:50', '2026-11-23 15:29:50')
