VALUES (NULL, NULL, 65445, 'Generation Zero', 'Generation Zero', 'game', 2019, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co66ky.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar56z.jpg', 'Generation Zero is a stealth-action shooter where you wage guerilla warfare against lethal mechanical enemies. Explore a vast open world map inspired by the Swedish Cold War era, take part in the resistance alone or with up to three friends in seamless co-op.', 'https://www.igdb.com/games/generation-zero', '["PlayStation 4", "PC (Microsoft Windows)", "PlayStation 5", "Xbox One"]', NULL, 5.9, 0, 8.99, '2026-11-23 15:29:50', '2026-11-23 15:29:50')
