VALUES (NULL, NULL, 11844, 'God Eater', 'God Eater', 'game', 2010, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2x2s.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/naau2b8h2zlskav2ywbq.jpg', 'God Eater is a Japanese action role-playing game and the first game in the God Eater series. The story revolves around the six members of the Far East Branch''s 1st Unit as part of a anti-Aragami organization called Fenrir. The game''s mission-based single-player mode consists of more than 100 missions, with co-operative play of up to three teammates over local adhoc wireless multiplayer or AI-controlled teammates.', 'https://www.igdb.com/games/god-eater', '["PlayStation Portable"]', NULL, 7.5, 0, 8.01, '2026-11-23 15:29:50', '2026-11-23 15:29:50')
