VALUES (NULL, NULL, 8658, 'Toukiden: The Age of Demons', 'Toukiden: The Age of Demons', 'game', 2013, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4hmk.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/s1crijhdmqsgauxajvck.jpg', 'An expansive fantasy world influenced by historical and traditional Japanese elements. This new franchise casts players in the role of the demon-fighting warrior, known as a Slayer. Starting from the Utakata Village headquarters where they will accept quests, players will venture out to battle monstrous and deadly Oni (demons) before they destroy all of humanity. Players can select party members from a supporting cast of characters, or join together with up to three other players through ad-hoc mode.', 'https://www.igdb.com/games/toukiden-the-age-of-demons', '["PlayStation Vita", "PlayStation Portable"]', NULL, 7.8, 0, 7.51, '2026-11-23 15:29:50', '2026-11-23 15:29:50')
