VALUES (NULL, NULL, 218793, 'Wild Hearts', 'Wild Hearts', 'game', 2023, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co66d3.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1x31.jpg', 'Prepare for an epic adventure set in a fantasy world inspired by feudal Japan. Developed by Omega Force, the Japanese studio behind Dynasty Warriors, in partnership with Electronic Arts.', 'https://www.igdb.com/games/wild-hearts', '["Xbox Series X|S", "PC (Microsoft Windows)", "PlayStation 5"]', NULL, 7.5, 0, 8.51, '2026-11-23 15:29:50', '2026-11-23 15:29:50')
