VALUES (NULL, NULL, 26166, 'Dauntless', 'Dauntless', 'game', 2019, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co93as.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar510.jpg', 'Dauntless takes place in a fantasy setting, where a cataclysmic event has torn the world apart, releasing monster-like Behemoths that prey on the surviving humans. As a Slayer of Ramsgate, you are all that stands between your world and the Behemoths that seek to devour it. Hunt huge monsters, alongside other Slayers on any platform, and craft awesome gear in this stylish free-to-play co-op action RPG.', 'https://www.igdb.com/games/dauntless', '["Xbox Series X|S", "PlayStation 4", "PC (Microsoft Windows)", "PlayStation 5", "Xbox One", "Nintendo Switch"]', NULL, 6.9, 0, 8.01, '2026-11-23 15:29:50', '2026-11-23 15:29:50')
