VALUES (NULL, NULL, 152202, 'Avatar: Frontiers of Pandora', 'Avatar: Frontiers of Pandora', 'game', 2023, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9oe3.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar69s3.jpg', 'Avatar: Frontiers of Pandora is a first-person, action-adventure game set in the never-before-seen Western Frontier of Pandora. Abducted by the human militaristic corporation known as the RDA, you, a Na’vi, were trained and molded to serve their purpose. Fifteen years later, you are free, but find yourself a stranger in your birthplace. Reconnect with your lost heritage, discover what it truly means to be Na''vi, and join other clans to protect Pandora from the RDA.', 'https://www.igdb.com/games/avatar-frontiers-of-pandora', '["Xbox Series X|S", "PC (Microsoft Windows)", "PlayStation 5"]', NULL, 7.3, 0, 8.52, '2026-11-23 15:29:50', '2026-11-23 15:29:50')
