VALUES (NULL, NULL, 960, 'Max Payne 3', 'Max Payne 3', 'game', 2012, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2mjo.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar63ox.jpg', 'Max Payne 3 is a third-person shooter in which the player assumes the role of its titular character, Max Payne. A new feature to the series, introduced in Max Payne 3, is the cover system, which allows players to gain a tactical advantage, and avoid taking damage from enemies. To progress through the linear story, players take on enemies throughout levels. The game features interactive cutscenes which transition seamlessly into continuing gameplay; there are no loading screens across gameplay and cutscenes.', 'https://www.igdb.com/games/max-payne-3', '["PlayStation 3", "PC (Microsoft Windows)", "Mac", "Xbox 360"]', NULL, 8.6, 0, 11.065, '2026-11-23 15:29:50', '2026-11-23 15:29:50')
