VALUES (NULL, NULL, 185246, 'Alan Wake II', 'Alan Wake II', 'game', 2023, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6jar.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar3nuh.jpg', 'Alan Wake 2 marks Remedy Entertainment’s first foray into the survival horror genre. Ritualistic murders in a small town. A writer trapped in a nightmare. An FBI agent looking for answers. Two realities. Two hero characters. One horror story that wants them dead.', 'https://www.igdb.com/games/alan-wake-ii', '["Xbox Series X|S", "PC (Microsoft Windows)", "PlayStation 5"]', NULL, 9.0, 0, 8.52, '2026-11-23 15:29:50', '2026-11-23 15:29:50')
