VALUES (NULL, NULL, 16, 'Fallout: New Vegas', 'Fallout: New Vegas', 'game', 2010, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1u60.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar4n6a.jpg', 'In this first-person Western RPG, the player takes on the role of Courier 6, barely surviving after being robbed of their cargo, shot and put into a shallow grave by a New Vegas mob boss. The Courier sets out to track down their robbers and retrieve their cargo, and winds up getting tangled in the complex ideological and socioeconomic web of the many factions and settlements of post-nuclear Nevada.', 'https://www.igdb.com/games/fallout-new-vegas', '["PlayStation 3", "PC (Microsoft Windows)", "Xbox 360"]', NULL, 8.5, 0, 13.3575, '2026-11-19 20:56:22', '2026-11-23 15:29:50')
