VALUES (NULL, NULL, 95032, 'Crying Suns', 'Crying Suns', 'game', 2019, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1vq8.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar9tz.jpg', 'Crying Suns is a tactical rogue-lite that puts you in the role of a space fleet commander as you explore a mysteriously fallen empire. In this story rich experience inspired by Dune and Foundation, each successful run will uncover the truth about the Empire... and yourself as well.', 'https://www.igdb.com/games/crying-suns', '["Android", "PC (Microsoft Windows)", "iOS", "Mac", "Nintendo Switch"]', NULL, 6.9, 0, 9.086666666666666e+00, '2026-11-19 20:56:22', '2026-11-23 15:29:50')
