VALUES (NULL, NULL, 533, 'Dishonored', 'Dishonored', 'game', 2012, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coabgu.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar3qne.jpg', 'Dishonored is an immersive first-person action game that casts you as a supernatural assassin driven by revenge. With Dishonored’s flexible combat system, creatively eliminate your targets as you combine the supernatural abilities, weapons and unusual gadgets at your disposal. Pursue your enemies under the cover of darkness or ruthlessly attack them head on with weapons drawn. The outcome of each mission plays out based on the choices you make.', 'https://www.igdb.com/games/dishonored', '["PlayStation 3", "PC (Microsoft Windows)", "Xbox 360"]', NULL, 8.5, 0, 11.55, '2026-11-21 13:07:40', '2026-11-23 15:29:50')
