VALUES (NULL, NULL, 1352, 'Journey', 'Journey', 'game', 2012, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cob9lk.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ekdes6jgjmwwfwlxpx6f.jpg', 'A third-person adventure game in which the player, controlling a robed figure, makes a pilgrimage through a desert landscape to a rugged mountain with a beacon of light in the distance while uncovering the history of their people, rescuing and cooperating with friendly creatures, avoiding predatory ones and communicating with other travelers.', 'https://www.igdb.com/games/journey', '["PlayStation 3", "PlayStation 4", "PC (Microsoft Windows)", "iOS"]', NULL, 9.0, 0, 10.53, '2026-11-21 13:07:40', '2026-11-23 15:29:50')
